CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(120) NOT NULL, email VARCHAR(255) UNIQUE NOT NULL, password TEXT NOT NULL, role VARCHAR(30) NOT NULL DEFAULT 'viewer' CHECK (role IN ('admin','operator','viewer')), last_login TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS metrics (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), service_name VARCHAR(120) NOT NULL, metric_type VARCHAR(120) NOT NULL, value NUMERIC NOT NULL, unit VARCHAR(30), metadata JSONB NOT NULL DEFAULT '{}'::jsonb, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS alerts (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(200) NOT NULL, service_name VARCHAR(120) NOT NULL, metric_type VARCHAR(120) NOT NULL, condition VARCHAR(20) NOT NULL, threshold NUMERIC NOT NULL, severity VARCHAR(20) NOT NULL DEFAULT 'medium' CHECK (severity IN ('low','medium','high','critical')), enabled BOOLEAN NOT NULL DEFAULT TRUE, acknowledged BOOLEAN NOT NULL DEFAULT FALSE, acknowledged_by UUID REFERENCES users(id) ON DELETE SET NULL, acknowledged_at TIMESTAMPTZ, created_by UUID REFERENCES users(id) ON DELETE SET NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_metrics_created_at ON metrics(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_metrics_service_type ON metrics(service_name, metric_type);
CREATE INDEX IF NOT EXISTS idx_alerts_created_at ON alerts(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_alerts_enabled ON alerts(enabled);
